<div class="mb-4"><div class="text-uppercase small accent fw-bold">Simulation lab</div><h1 class="fw-bold">FoodHub Digital Twin</h1><p class="text-secondary">Use live operational data as the baseline, then test demand, kitchen and delivery capacity scenarios.</p></div>
<div id="login" class="card food-card p-4 mb-4"><form id="f" class="row g-3"><div class="col-md-5"><input id="email" class="form-control" type="email" placeholder="admin or manager email"></div><div class="col-md-5"><input id="password" class="form-control" type="password" placeholder="Enter password"></div><div class="col-md-2"><button class="btn btn-fh w-100">Open Twin</button></div></form><div id="msg" class="small mt-2"></div></div>
<div id="app" class="d-none"><div class="row g-4"><div class="col-lg-4"><div class="card food-card p-4"><h5>Scenario</h5><label class="form-label">Orders/day</label><input id="orders" class="form-control" type="number" value="100"><label class="form-label mt-2">Demand growth %</label><input id="growth" class="form-control" type="number" value="20"><label class="form-label mt-2">Riders</label><input id="riders" class="form-control" type="number" value="8"><label class="form-label mt-2">Kitchen capacity/hour</label><input id="kitchen" class="form-control" type="number" value="30"><label class="form-label mt-2">Average order value</label><input id="aov" class="form-control" type="number" value="350"><label class="form-label mt-2">Operating hours</label><input id="hours" class="form-control" type="number" value="12"><button class="btn btn-fh w-100 mt-3" onclick="simulate()">Run simulation</button></div></div><div class="col-lg-8"><div class="card food-card p-4"><h5>Baseline</h5><pre id="baseline" class="bg-light p-3 rounded"></pre><h5>Projection</h5><div id="result" class="row g-3"></div></div></div></div></div>
<?php $__env->stopSection(); ?>
<?php $__env->startPush('scripts'); ?><script>
let t=localStorage.getItem('fh_branch_token')||'';async function api(u,o={}){o.headers={...(o.headers||{}),Accept:'application/json','Content-Type':'application/json',Authorization:'Bearer '+t};const r=await fetch(u,o),d=await r.json();if(!r.ok)throw Error(d.message||'Request failed');return d;}async function openTwin(){try{if(!t){const r=await fetch('/api/v1/auth/login',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({email:email.value,password:password.value})});const d=await r.json();if(!r.ok)throw Error(d.message||'Login failed');t=d.token;localStorage.setItem('fh_branch_token',t);}const s=await api('/api/v1/digital-twin/snapshot');baseline.textContent=JSON.stringify(s,null,2);login.classList.add('d-none');app.classList.remove('d-none');}catch(e){msg.textContent=e.message;msg.className='small mt-2 text-danger';}}async function simulate(){try{const d=await api('/api/v1/digital-twin/simulate',{method:'POST',body:JSON.stringify({orders_per_day:Number(orders.value),demand_growth_percent:Number(growth.value),riders:Number(riders.value),kitchen_capacity_per_hour:Number(kitchen.value),average_order_value:Number(aov.value),operating_hours:Number(hours.value)})});const p=d.projection;result.innerHTML=[['Projected orders/day',p.projected_orders_per_day],['Projected sales/day','₱'+Number(p.projected_sales_per_day).toLocaleString()],['Kitchen load',p.kitchen_load_percent+'%'],['Delivery load',p.delivery_load_percent+'%'],['Unserved estimate',p.unserved_order_estimate]].map(x=>`<div class="col-md-6"><div class="card stat p-3"><small class="text-secondary">${x[0]}</small><div class="fs-4 fw-bold">${x[1]}</div></div></div>`).join('');}catch(e){alert(e.message)}}f.addEventListener('submit',e=>{e.preventDefault();openTwin()});if(t)openTwin();</script><?php $__env->stopPush(); ?>

<?php echo $__env->make('layouts.app', array_diff_key(get_defined_vars(), ['__data' => 1, '__path' => 1]))->render(); ?><?php /**PATH C:\xampp\htdocs\FoodHub-Advanced-Portal-Login-Redesign-Fixed2\backend\resources\views/digital-twin.blade.php ENDPATH**/ ?>